create or replace function public.learning_load_snapshot(p_workspace_id uuid) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare d jsonb;
begin
if auth.uid() is null or public.ws_access_level(p_workspace_id,'learning','main') not in('view','edit') then raise exception 'Learning workspace access denied' using errcode='42501';end if;
select jsonb_build_object('version',1,'areas',coalesce((select jsonb_agg(payload) from public.learning_areas where workspace_id=p_workspace_id),'[]'::jsonb),'courses',coalesce((select jsonb_agg(payload) from public.learning_courses where workspace_id=p_workspace_id),'[]'::jsonb),'units',coalesce((select jsonb_agg(payload) from public.learning_units where workspace_id=p_workspace_id),'[]'::jsonb),'lessons',coalesce((select jsonb_agg(payload) from public.learning_lessons where workspace_id=p_workspace_id),'[]'::jsonb),'sessions',coalesce((select jsonb_agg(payload order by event_date desc nulls last) from public.learning_sessions where workspace_id=p_workspace_id),'[]'::jsonb),'skills',coalesce((select jsonb_agg(payload) from public.learning_skills where workspace_id=p_workspace_id),'[]'::jsonb),'assessments',coalesce((select jsonb_agg(payload order by event_date desc nulls last) from public.learning_assessments where workspace_id=p_workspace_id),'[]'::jsonb),'careerGoals',coalesce((select jsonb_agg(payload) from public.learning_career_goals where workspace_id=p_workspace_id),'[]'::jsonb),'vocabulary',coalesce((select jsonb_agg(payload order by event_date nulls last) from public.learning_vocabulary where workspace_id=p_workspace_id),'[]'::jsonb),'reviewLogs',coalesce((select jsonb_agg(payload order by event_date desc nulls last) from public.learning_review_logs where workspace_id=p_workspace_id),'[]'::jsonb),'preferences',coalesce((select preferences from public.learning_workspace_state where workspace_id=p_workspace_id),'{"dailyGoalMinutes":30,"weeklyGoalMinutes":720}'::jsonb)) into d;
return jsonb_build_object('data',d,'updatedAt',(select updated_at from public.learning_workspace_state where workspace_id=p_workspace_id));
end;$$;
create or replace function public.learning_save_snapshot(p_workspace_id uuid,p_snapshot jsonb,p_expected_updated_at timestamptz default null) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare n timestamptz:=clock_timestamp();c timestamptz;col text;tab text;pk text;r jsonb;
begin
if auth.uid() is null or public.ws_access_level(p_workspace_id,'learning','main')<>'edit' then raise exception 'Learning workspace edit access denied' using errcode='42501';end if;
if jsonb_typeof(p_snapshot)<>'object' then raise exception 'Invalid learning snapshot';end if;
perform pg_advisory_xact_lock(hashtext(p_workspace_id::text));
select updated_at into c from public.learning_workspace_state where workspace_id=p_workspace_id for update;
if c is distinct from p_expected_updated_at and not(c is null and p_expected_updated_at is null) then return jsonb_build_object('ok',false,'conflict',true,'updatedAt',c);end if;
for col,tab,pk in select * from(values('areas','learning_areas',''),('courses','learning_courses','areaId'),('units','learning_units','courseId'),('lessons','learning_lessons','unitId'),('sessions','learning_sessions','lessonId'),('skills','learning_skills','areaId'),('assessments','learning_assessments','areaId'),('careerGoals','learning_career_goals','skillId'),('vocabulary','learning_vocabulary','areaId'),('reviewLogs','learning_review_logs','vocabularyId')) as x(collection,table_name,parent_key)
loop
for r in select value from jsonb_array_elements(coalesce(p_snapshot->col,'[]'::jsonb)) loop
execute format('insert into public.%I(workspace_id,id,parent_id,event_date,minutes,score,max_score,payload) values($1,$2,$3,$4,$5,$6,$7,$8) on conflict(workspace_id,id) do update set parent_id=excluded.parent_id,event_date=excluded.event_date,minutes=excluded.minutes,score=excluded.score,max_score=excluded.max_score,payload=excluded.payload',tab)
using p_workspace_id,r->>'id',nullif(r->>pk,''),nullif(coalesce(r->>'sessionDate',r->>'assessmentDate',r->>'dueDate',r->>'reviewDate',r->>'targetDate',r->>'studyDate'),'')::date,case when col='sessions' then coalesce(nullif(r->>'minutes','')::int,0) else null end,case when col='assessments' then nullif(r->>'score','')::numeric else null end,case when col='assessments' then nullif(r->>'maxScore','')::numeric else null end,r;
end loop;end loop;
insert into public.learning_workspace_state(workspace_id,updated_at,updated_by,preferences) values(p_workspace_id,n,auth.uid(),coalesce(p_snapshot->'preferences','{"dailyGoalMinutes":30,"weeklyGoalMinutes":720}'::jsonb)) on conflict(workspace_id) do update set updated_at=excluded.updated_at,updated_by=excluded.updated_by,preferences=excluded.preferences;
return jsonb_build_object('ok',true,'conflict',false,'updatedAt',n);
end;$$;
revoke all on function public.learning_load_snapshot(uuid) from public,anon;revoke all on function public.learning_save_snapshot(uuid,jsonb,timestamptz) from public,anon;grant execute on function public.learning_load_snapshot(uuid) to authenticated;grant execute on function public.learning_save_snapshot(uuid,jsonb,timestamptz) to authenticated;grant select,insert,update,delete on public.learning_areas,public.learning_courses,public.learning_units,public.learning_lessons,public.learning_sessions,public.learning_skills,public.learning_assessments,public.learning_career_goals,public.learning_vocabulary,public.learning_review_logs,public.learning_workspace_state to authenticated;